      {Node(0);}	    Node(Fields v) {type = FieldNode; value._field = v;}	    Node(CardType v) {type = CardTypeNode; value._ctype = v;}	    Node(int v) {type = IntNode; value._int = v;}	    Node(char* v) {type = StringNode; value._string = v;}	    Node(Tree* v) {type = IntNode; value._tree = v;}	void* operator new (long bytes);	// dyn. allocated node	void  operator delete (void* ptr);	// free a dyn. allocated node};class Tree {	const blocksize = 100;	// number of trees to allocate at a time	const maxblocks = 10;	// maximum number of blocks to allocate.	static int numblocks;	// current number of allocated blocks	static Tree* blocks[maxblocks]; // allocated trees	static Tree* freelist;	// linked list of available trees	void   moreblocks();	// internal functio to get another block of treespublic:	Operators oper;	Node* right;	Node* left;	      Tree() // new tree	        {Tree(Equal,0,0);}	      Tree(Operators o,Node* l,Node* r)	        {oper = o;right = r; left = l;}	void* operator new (long bytes);	// dyn. allocated node	void  operator delete (void* ptr);	// free a dyn. allocated node};#endif